using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using System.Text;using System.Web.Script.Serialization;
namespace PZ3D {static class FeedbackTests {
 static int checks;static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=1048576};
 static void Check(bool ok,string why){if(!ok)throw new Exception("FAIL: "+why);checks++;}
 static Dictionary<string,object> Map(object value){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(value));}
 static object Call(object service,string method,params object[] args){try{return service.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(service,args);}catch(TargetInvocationException ex){throw ex.InnerException;}}
 static void Reject(Action action,string why){bool refused=false;try{action();}catch{refused=true;}Check(refused,why);}
 static Dictionary<string,object> P(params object[] a){var d=new Dictionary<string,object>();for(int i=0;i<a.Length;i+=2)d[(string)a[i]]=a[i+1];return d;}
 public static int Main(){string root=Path.Combine(Path.GetTempPath(),"ozl-feedback-"+Guid.NewGuid().ToString("N"));try{
  var request=P("id","feedback-test","action","feedbackPreview","payload",P("description","无法进入服务器","gameLog",true,"launcherLog",false,"system",false));
  try{ModernHostPolicy.Validate("https://orange.local/index.html",Json.Serialize(request));}catch(Exception ex){throw new Exception("FAIL: consent preview is available through the trusted native bridge",ex);}
  Check(true,"trusted preview action accepted");var type=typeof(Engine).Assembly.GetType("PZ3D.FeedbackService");Check(type!=null,"native feedback service exists");
  string game=Path.Combine(root,"game"),user=Path.Combine(root,"user"),data=Path.Combine(root,"data");Directory.CreateDirectory(game);Directory.CreateDirectory(user);Directory.CreateDirectory(Path.Combine(data,"diagnostics"));
  File.WriteAllText(Path.Combine(game,"ProjectZomboid64.json"),"{\"vmArgs\":[\"-Xmx2g\"]}");File.WriteAllText(Path.Combine(user,"console.txt"),"useful exception\npassword=private-secret\nsteamid=76561198000000001\nC:\\Users\\PrivatePlayer\\secret\\console.txt\nserver=198.51.100.20\nCHAT: hidden chat\nLOG  : General f:0, t:12345> CHAT: prefixed-private-message\ncontinuation-private-message\nLOG  : General f:1> technical exception\n");
  File.WriteAllText(Path.Combine(data,"diagnostics","launcher.log"),"launcher useful exception");var engine=new Engine(game,user,data,true);int sends=0,hardware=0;byte[] uploaded=null;DateTime now=DateTime.UtcNow;
  Func<byte[],Dictionary<string,object>> send=b=>{sends++;uploaded=b;var body=Json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(b));return P("id",body["requestId"],"receivedUtc",now.ToString("o"),"status","received");};
  Func<Dictionary<string,object>> system=()=>{hardware++;return P("os","Synthetic OS","architecture","X64","cpu","Synthetic CPU","logicalProcessors",8,"totalMemoryGiB",32,"gpu","Synthetic GPU","vramGiB",8,"driver","1.0");};
  Func<DateTime> clock=()=>now;var service=Activator.CreateInstance(type,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,new object[]{engine,send,system,clock},null);
  var empty=Map(Call(service,"Preview",P("description","只发送问题描述","gameLog",false,"launcherLog",false,"system",false)));Check(sends==0&&hardware==0,"preview without system consent performs no network or hardware query");Check(((System.Collections.ICollection)empty["files"]).Count==0&&empty["system"]==null,"unselected documents and hardware are absent");
  var preview=Map(Call(service,"Preview",P("description","进服出错","gameLog",true,"launcherLog",false,"system",true)));Check(sends==0&&hardware==1,"selected hardware is collected once at preview only");string token=(string)preview["token"],id=(string)preview["id"];string text=Json.Serialize(preview);Check(text.Contains("useful exception")&&!text.Contains("private-secret")&&!text.Contains("76561198000000001")&&!text.Contains("PrivatePlayer")&&!text.Contains("198.51.100.20")&&!text.Contains("hidden chat")&&!text.Contains("prefixed-private-message")&&!text.Contains("continuation-private-message"),"preview redacts credentials, identifiers, addresses, paths and chat");
  Reject(()=>Call(service,"Send",P("token",token,"confirmed",false)),"send requires explicit consent");Check(sends==0,"rejected send does not contact server");
  File.AppendAllText(Path.Combine(user,"console.txt"),"new unseen private material\n");var sent=Map(Call(service,"Send",P("token",token,"confirmed",true)));Check(sends==1&&(string)sent["id"]==id&&!Encoding.UTF8.GetString(uploaded).Contains("new unseen"),"send uploads exactly the reviewed snapshot");Call(service,"Send",P("token",token,"confirmed",true));Check(sends==1,"same consent cannot create a second upload");
  var history=Map(Call(service,"Status"));Check(((System.Collections.ICollection)history["history"]).Count==1,"confirmed server receipt is recorded locally");
  Call(service,"Preview",P("description","新的反馈","gameLog",false,"launcherLog",true,"system",false));Reject(()=>Call(service,"Send",P("token",token,"confirmed",true)),"new preview revokes earlier token");
  var exp=Map(Call(service,"Preview",P("description","过期反馈","gameLog",false,"launcherLog",false,"system",false)));now=now.AddMinutes(11);Reject(()=>Call(service,"Send",P("token",exp["token"],"confirmed",true)),"expired snapshot requires a new preview");
  request["payload"]=P("description","no","gameLog",false,"launcherLog",false,"system",false,"path","C:/secret");Reject(()=>ModernHostPolicy.Validate("https://orange.local/index.html",Json.Serialize(request)),"web UI cannot supply a collection path");
  var longPreview=Map(Call(service,"Preview",P("description",string.Concat(Enumerable.Repeat("a\n",1000)),"gameLog",false,"launcherLog",false,"system",false)));Check(((string)longPreview["description"]).Length<=2000,"valid newline description fits the server limit after sanitization");
  int retryCount=0;byte[] firstAttempt=null;Func<byte[],Dictionary<string,object>> retry=b=>{retryCount++;if(firstAttempt==null){firstAttempt=(byte[])b.Clone();throw new IOException("synthetic temporary network failure");}Check(firstAttempt.SequenceEqual(b),"retry preserves original ID, timestamp and exact reviewed bytes");var wire=Json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(b));return P("id",wire["requestId"],"receivedUtc",now.ToString("o"),"status","received");};
  var retryService=Activator.CreateInstance(type,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,new object[]{engine,retry,system,clock},null);var retryPreview=Map(Call(retryService,"Preview",P("description","synthetic retry","gameLog",false,"launcherLog",false,"system",false)));Reject(()=>Call(retryService,"Send",P("token",retryPreview["token"],"confirmed",true)),"network failure does not claim receipt");Check(((System.Collections.ICollection)Map(Call(retryService,"Status"))["history"]).Count==1,"failed send adds no successful history");Call(retryService,"Send",P("token",retryPreview["token"],"confirmed",true));Check(retryCount==2,"explicit retry can finish once");
  var optionsRequest=P("id","loading-options","action","loadingSetEnabled","payload",P("enabled",false,"confirmed",true));ModernHostPolicy.Validate("https://orange.local/index.html",Json.Serialize(optionsRequest));optionsRequest["payload"]=P("enabled",false,"confirmed",true,"path",game);Reject(()=>ModernHostPolicy.Validate("https://orange.local/index.html",Json.Serialize(optionsRequest)),"loading controls cannot provide target paths");
  Check(!Directory.GetFiles(data,"*",SearchOption.AllDirectories).Any(p=>File.ReadAllText(p).Contains("private-secret")),"local receipts do not persist raw logs");
  Console.WriteLine("PASS "+checks+" feedback selection, preview, redaction, consent and receipt checks");return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}
}}
